// Independent local CEDD height-field adapter. No source terrain or building height is modified.
// Coefficients encode a shared hierarchical hat basis; output geometry is generated by the host.
const finite=(...v)=>v.every(Number.isFinite);
function cell(a,x){if(x<a[0]||x>a.at(-1))return -1;let lo=0,hi=a.length-1;while(hi-lo>1){const m=(lo+hi)>>1;if(a[m]<=x)lo=m;else hi=m;}return Math.min(lo,a.length-2);}
function basisAt(coeff,l,x,y){const i=cell(l.xs,x),j=cell(l.ys,y);if(i<0||j<0)return null;const u=(x-l.xs[i])/(l.xs[i+1]-l.xs[i]),v=(y-l.ys[j])/(l.ys[j+1]-l.ys[j]),k=l.offsetScalar+j*l.shapeRC[1]+i,w=l.shapeRC[1];return (coeff[k]*(1-u)+coeff[k+1]*u)*(1-v)+(coeff[k+w]*(1-u)+coeff[k+w+1]*u)*v;}
export function sampleTriangle(level,E,N){if(!finite(E,N))return null;const cf=(E-level.x0)/level.step,rf=(level.y0-N)/level.step;if(cf<0||rf<0||cf>level.width-1||rf>level.height-1)return null;const c=Math.min(level.width-2,Math.floor(cf)),r=Math.min(level.height-2,Math.floor(rf)),u=cf-c,v=rf-r,j=r*level.width+c,A=j,B=j+1,C=j+level.width,D=C+1;const ids=u+v<=1?[A,C,B]:[B,C,D];if(ids.some(i=>level.mask[i]!==1||!Number.isFinite(level.heights[i])))return null;const a=level.heights[A],b=level.heights[B],c0=level.heights[C],d=level.heights[D];return u+v<=1?a+(b-a)*u+(c0-a)*v:d+(c0-d)*(1-u)+(b-d)*(1-v);}
export function createPatch(meta,coefficients){if(coefficients.length*8!==meta.coefficients.decodedBytes)throw Error('Coefficient length mismatch');if(meta.step!==2||meta.maskEncoding?.value!==1||meta.sourceWeightEncoding?.value!==255)throw Error('Unsupported candidate contract');const heights=new Float32Array(meta.width*meta.height);for(let r=0;r<meta.height;r++)for(let c=0;c<meta.width;c++){let value=0;for(const l of meta.levels){const h=basisAt(coefficients,l,c,r);if(h===null)throw Error('Incomplete basis domain');value+=h;}heights[r*meta.width+c]=value;}const mask=new Uint8Array(heights.length).fill(1),weight=new Uint8Array(heights.length).fill(255),level={x0:meta.x0,y0:meta.y0,step:2,width:meta.width,height:meta.height,heights,mask,weight};return {meta,hostPatch:{id:meta.id,label:meta.label,bounds_epsg2326:meta.bounds_epsg2326,source_bounds_epsg2326:meta.source_bounds_epsg2326,levels:{'2':level},sourceNativeSpacingM:0.5,runtimeGridStepsM:[2],candidateNoOuterTransition:true},sample:(E,N)=>sampleTriangle(level,E,N)};}
export function boundsCoveredByRectangles(b,rects){if(!Array.isArray(b)||b.length!==4||!finite(...b)||b[0]>b[2]||b[1]>b[3])return false;const inside=(x,y)=>rects.some(a=>x>=a[0]&&x<=a[2]&&y>=a[1]&&y<=a[3]);const xs=[b[0],b[2],...rects.flatMap(a=>[a[0],a[2]]).filter(x=>x>b[0]&&x<b[2])].sort((a,b)=>a-b),ys=[b[1],b[3],...rects.flatMap(a=>[a[1],a[3]]).filter(y=>y>b[1]&&y<b[3])].sort((a,b)=>a-b);for(const x of xs)for(const y of ys)if(!inside(x,y))return false;for(let i=0;i<xs.length-1;i++)for(let j=0;j<ys.length-1;j++)if(!inside((xs[i]+xs[i+1])/2,(ys[j]+ys[j+1])/2))return false;return true;}
async function sha(bytes){if(!globalThis.crypto?.subtle)return null;return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),n=>n.toString(16).padStart(2,'0')).join('');}
export async function openCEDDTerrainIncrement(manifestUrl,{fetchImpl=fetch}={}){const absolute=new URL(manifestUrl,globalThis.location?.href||'file:///').href,r=await fetchImpl(absolute);if(!r.ok)throw Error('Manifest HTTP '+r.status);const manifest=await r.json();if(manifest.schema!=='kaopu.hk.cedd-local-height-spectrum/0.1')throw Error('Unsupported terrain spectrum');const decoded=await Promise.all(manifest.patches.map(async meta=>{const response=await fetchImpl(new URL(meta.coefficients.url,absolute).href);if(!response.ok)throw Error('Coefficient HTTP '+response.status);const encoded=await response.arrayBuffer(),hash=await sha(encoded);if(hash&&hash!==meta.coefficients.sha256)throw Error('Coefficient SHA256 mismatch');const raw=await new Response(new Blob([encoded]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();if(raw.byteLength!==meta.coefficients.decodedBytes)throw Error('Decoded size mismatch');const a=new Float64Array(raw.byteLength/8),view=new DataView(raw);for(let i=0;i<a.length;i++)a[i]=view.getFloat64(i*8,true);return createPatch(meta,a);}));return {manifest,patches:decoded.map(p=>p.hostPatch),sampleHeight(E,N){for(const p of decoded){const h=p.sample(E,N);if(h!==null)return h;}return null;},boundsCovered:b=>boundsCoveredByRectangles(b,manifest.patches.map(p=>p.bounds_epsg2326)),getPatch:id=>decoded.find(p=>p.meta.id===id)||null};}
